  ('ACE', 'high_school', '{"title":"นักออกแบบผู้คุมเกม","summary":"คุณมีความคิดสร้างสรรค์ ทำงานอย่างเป็นระบบ และกล้ารับผิดชอบผลลัพธ์ คุณเหมาะกับงานที่ต้องดูแลภาพรวมของงานสร้างสรรค์ ให้ทั้งสวย ตรงเป้า และเป็นไปตามแผน","strengths":[{"title":"คุมคุณภาพงานสร้างสรรค์","detail":"ทำให้ทุกชิ้นงานอยู่ในมาตรฐานเดียวกัน"},{"title":"วางแผนและติดตาม","detail":"รู้ว่าแต่ละส่วนต้องเสร็จเมื่อไร"},{"title":"ตัดสินใจเรื่องภาพลักษณ์","detail":"เลือกทิศทางที่เหมาะกับแบรนด์หรือองค์กร"},{"title":"สื่อสารชัดเจน","detail":"บอกทีมได้ตรงว่าต้องการอะไร"}],"careers":[{"title":"ผู้จัดการแบรนด์","reason":"ดูแลภาพลักษณ์และแผนการตลาดของแบรนด์ให้สอดคล้องกัน","tag":"นำทีม • สร้างสรรค์"},{"title":"บรรณาธิการบริหารนิตยสารและสื่อออนไลน์","reason":"กำหนดทิศทางเนื้อหาและคุมทีมให้ส่งงานตรงเวลา","tag":"นำทีม • จัดระบบ"},{"title":"ผู้จัดการฝ่ายสร้างสรรค์","reason":"วางระบบการทำงานของทีมออกแบบและคุมคุณภาพ","tag":"สร้างสรรค์ • นำทีม"},{"title":"ผู้ซื้อสินค้าแฟชั่น (buyer)","reason":"เลือกสินค้าที่เข้ากับแบรนด์และคุมงบซื้ออย่างแม่นยำ","tag":"สร้างสรรค์ • จัดระบบ"},{"title":"นักวางแผนสื่อโฆษณา","reason":"เลือกช่องทางและงบโฆษณาให้ได้ผลคุ้มค่าที่สุด","tag":"จัดระบบ • นำทีม"},{"title":"ผู้จัดการโครงการสร้างสรรค์","reason":"ประสานนักออกแบบ ลูกค้า และกำหนดส่งงาน","tag":"นำทีม • จัดระบบ"}],"guidance":[{"title":"การตลาด","tag":"บริหารธุรกิจ","detail":"เรียนการเข้าใจผู้บริโภคและวางแผนแบรนด์จากข้อมูล","programs":[{"university":"มหาวิทยาลัยเกษตรศาสตร์","campus":"กำแพงแสน","faculty":"คณะศิลปศาสตร์และวิทยาศาสตร์","program":"บธ.บ. สาขาวิชาการตลาด","url":"https://course.mytcas.com/programs/10020222610601A","fieldUrl":"https://course.mytcas.com/universities/002/faculties/22/fields/06","rounds":["รอบ 2","รอบ 3"]},{"university":"มหาวิทยาลัยศิลปากร","campus":"เมืองทองธานี","faculty":"คณะวิทยาการจัดการ","program":"หลักสูตรบริหารธุรกิจบัณฑิต สาขาวิชาการตลาด","url":"https://course.mytcas.com/programs/10080412610601B","fieldUrl":"https://course.mytcas.com/universities/008/faculties/12/fields/06","rounds":["รอบ 1","รอบ 3"]},{"univers